import {verifyLocalReferenceLog} from '../../scripts/tp-reference-local.mjs';
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,cpSync,realpathSync} from 'node:fs';
import {resolve,dirname,sep} from 'node:path';
import {execFileSync,spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {verifyExperiments,verifyEvaluation,verifyF05Matrix,assertOpenStockProductionExcluded} from '../../scripts/tp11-evaluation.mjs';
import {root,digest,inventory,nodesFromPlans,planInput,validateReceipt} from '../../scripts/provider-a1-receipts.mjs';
export const directory='docs/audit/evidence/tp11-20261011';
export const selectors=['scripts/tp-reference-local.mjs','third_party/openstock/','engines/engine-sdk/','engines/openbb-adapter/src/openbb_adapter/contracts/','engines/tests/test_tp11_openstock_fixtures.py','engines/uv.lock','engines/pyproject.toml','proto/','crates/quantos-storage/','scripts/tp11*','scripts/check-tp-intake.mjs','scripts/generate-build-manifest.mjs','Makefile','scripts/provider-a1-receipts.mjs','scripts/provider-a1-policy.json','docs/adr/20260731-tp11-openstock-evaluation.md'];
const files=['third_party/openstock/experiments.py','engines/tests/test_tp11_openstock_fixtures.py'];
export const checks=[
 {id:'contract',command:['engines/.venv/bin/python','-m','pytest',files[1],'-vv'],marker:/45 passed/},
 {id:'experiments',command:['engines/.venv/bin/python',files[0],'--output','artifacts/tp11-development'],marker:/"replayIdentical": true/},
 {id:'schema',command:['node','scripts/tp11-evaluation.mjs','artifacts/tp11-development'],marker:/TP11_OFFLINE_SCHEMA_PASS/},
 {id:'evaluation',command:['node','scripts/tp11-evaluation.mjs','--workspace'],marker:/TP11_EVALUATION_PASS/},
 {id:'upstream',command:['node','scripts/tp11-evaluation.mjs','--verify-upstream'],marker:/TP11_PINNED_PUBLIC_DIGESTS_PASS/},
 {id:'negatives',command:['node','--test','scripts/tp11-evaluation.test.mjs'],marker:/fail\s+0/},
 {id:'f05',command:['cargo','test','--locked','--offline','-p','quantos-storage','--test','tp11_reference_gate','--','--nocapture'],marker:/2 passed; 0 failed/},
 {id:'lint',command:['engines/.venv/bin/ruff','check',...files],marker:/All checks passed/},
 {id:'format',command:['engines/.venv/bin/ruff','format','--check',...files],marker:/2 files already formatted/},
 {id:'types',command:['engines/.venv/bin/pyright','--pythonpath','engines/.venv/bin/python','--pythonversion','3.12',...files],marker:/0 errors/},
 {id:'locks',command:['bash','scripts/check-lockfiles.sh'],marker:/All phase-1 locks parse and match their manifests/},
 {id:'intake',command:['node','scripts/check-tp-intake.mjs'],marker:/unapproved upstream packages are absent/},
];
export const localChecks=checks.map(c=>c.id==='upstream'?{id:'reference-local',command:['node','scripts/tp-reference-local.mjs','TP11'],marker:/LOCAL_REFERENCE_METADATA_PASS/}:c);
export const checksFor=r=>{assert(['UPSTREAM','LOCAL'].includes(r.validationMode??'UPSTREAM'));return r.validationMode==='LOCAL'?localChecks:checks;};
const excluded=['upstream source/assets/runtime, hosted OpenStock or Day-1 dependency','real Finnhub or widget data, written business/redistribution rights or legal approval','TP05 provider/schema extension, deployed provider, database or persistent Artifact delivery','implemented research UI, strategy Engine, trading or venue access','current advisory clearance, representative performance, hosted same-SHA CI, publication or formal ACCEPTED'];
const deps=()=>nodesFromPlans().get('CORE:TP11').dependencies.map(nodeId=>{try{return{nodeId,...validateReceipt(nodeId)};}catch(e){return{nodeId,status:'BLOCKED',reason:e.message.split('\n')[0]};}});
export function verifyTp11(r,{checkDependencies=true,logDirectory=resolve(root,directory)}={}){
 assert.equal(r.schema,'quantos-tp11-development/v1');assert.equal(r.nodeId,'CORE:TP11');assert.equal(r.stage,'DEVELOPMENT');assert.equal(r.formalAccepted,false);assert.equal(r.engineeringStatus,'PASS');assert(['READY','BLOCKED'].includes(r.status));assert.deepEqual(r.excluded,excluded);assert.deepEqual(r.inputs,inventory(selectors),'TP11 functional inputs changed');assert.deepEqual(r.planInput,planInput(nodesFromPlans().get(r.nodeId)));assert(/^[a-f0-9]{40}$/.test(r.observedSourceCommit));assert(r.environment.node&&r.environment.python);assert.deepEqual(r.checks.map(c=>c.id),checksFor(r).map(c=>c.id));
 for(const [i,c]of r.checks.entries()){const spec=checksFor(r)[i];assert.deepEqual(c.command,spec.command);assert.equal(c.exitCode,0);assert.equal(c.status,'PASS');assert(Number.isFinite(Date.parse(c.executedAt))&&Date.parse(c.executedAt)<=Date.now());assert.equal(c.log,directory+'/'+spec.id+'.log');const bytes=readFileSync(resolve(logDirectory,spec.id+'.log'));assert.equal(digest(bytes),c.logSha256,'TP11 log changed');assert.match(bytes.toString(),spec.marker);}
 if(r.validationMode==='LOCAL'){assert.deepEqual(r.upstreamVerification,{status:'NOT_RUN',checkpoint:'RELEASE-GATE:BETA',externalExecution:false,currentPublicBytesVerified:false});verifyLocalReferenceLog(readFileSync(resolve(logDirectory,'reference-local.log'),'utf8'),'TP11');}else{const proof=JSON.parse(readFileSync(resolve(root,'third_party/openstock/provenance.json')));const online=readFileSync(resolve(logDirectory,'upstream.log'),'utf8').split('\n').filter(l=>l.startsWith('{')).map(l=>JSON.parse(l));assert.deepEqual(online.slice(0,6),proof.files.map(f=>({...f,retained:false})));assert.equal(online.length,8);for(const [i,t]of proof.terms.entries()){const o=online[6+i];assert.equal(o.terms,t.id);assert.equal(o.url,t.url);assert.equal(o.admission,t.admission);assert.equal(o.retained,false);assert(/^[a-f0-9]{64}$/.test(o.sha256));assert(o.sizeBytes>0);}}
 const experiment=JSON.parse(readFileSync(resolve(logDirectory,'experiments/receipt.json')));assert.deepEqual(r.outputs.map(o=>o.file),['experiments/receipt.json',...experiment.files.map(f=>'experiments/'+f.file),'f05-gate.json']);for(const o of r.outputs){assert(typeof o.file==='string'&&!o.file.includes('..')&&!o.file.includes('\\')&&!o.file.startsWith('/'),'TP11 unsafe output path');const path=realpathSync(resolve(logDirectory,o.file));assert(path.startsWith(realpathSync(logDirectory)+sep),'TP11 output escapes evidence');assert.equal(digest(readFileSync(path)),o.sha256,'TP11 output evidence changed');}verifyExperiments(resolve(logDirectory,'experiments'));const lines=readFileSync(resolve(logDirectory,'f05.log'),'utf8').split('\n').filter(l=>l.startsWith('TP11_F05_GATE='));assert.equal(lines.length,1);const matrix=JSON.parse(readFileSync(resolve(logDirectory,'f05-gate.json')));assert.deepEqual(matrix,JSON.parse(lines[0].slice('TP11_F05_GATE='.length)));verifyF05Matrix(matrix);verifyEvaluation();assertOpenStockProductionExcluded([]);
 if(checkDependencies){assert.deepEqual(r.dependencies,deps());assert.equal(r.status,r.dependencies.every(d=>d.status==='READY')?'READY':'BLOCKED');if(r.status==='READY')validateReceipt('CORE:TP11');}
 return{engineeringStatus:'PASS',stageGate:checkDependencies?r.status:'NOT_ASSESSED',formalAccepted:false};
}
function record(local=false){const inputs=inventory(selectors);mkdirSync(resolve(root,directory),{recursive:true});const results=(local?localChecks:checks).map(spec=>{const executedAt=new Date().toISOString();const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>!/DATABASE_URL|SUPABASE|PASSWORD|TOKEN|KEY|SECRET|QUANTOS_RUN_.*TESTS|QUANTOS_TRACE_EXPORT_PATH|QUANTOS_ENGINE/.test(k)));const run=spawnSync(spec.command[0],spec.command.slice(1),{cwd:root,encoding:'utf8',timeout:300000,maxBuffer:16*1024*1024,env});const output=(run.stdout??'')+(run.stderr??'');const log=directory+'/'+spec.id+'.log';writeFileSync(resolve(root,log),output);console.log(spec.id,run.status);return{id:spec.id,command:spec.command,executedAt,exitCode:run.status,status:run.status===0?'PASS':'FAIL',log,logSha256:digest(output)};});assert.deepEqual(inputs,inventory(selectors));const experiment=JSON.parse(readFileSync(resolve(root,'artifacts/tp11-development/receipt.json')));const outputs=['receipt.json',...experiment.files.map(f=>f.file)].map(file=>{const destination=resolve(root,directory,'experiments',file);mkdirSync(dirname(destination),{recursive:true});cpSync(resolve(root,'artifacts/tp11-development',file),destination);return{file:'experiments/'+file,sha256:digest(readFileSync(destination))};});const lines=readFileSync(resolve(root,directory,'f05.log'),'utf8').split('\n').filter(l=>l.startsWith('TP11_F05_GATE='));assert.equal(lines.length,1);const matrix=JSON.parse(lines[0].slice('TP11_F05_GATE='.length));const bytes=JSON.stringify(matrix,null,2)+'\n';writeFileSync(resolve(root,directory,'f05-gate.json'),bytes);outputs.push({file:'f05-gate.json',sha256:digest(bytes)});const dependencies=deps();const r={schema:'quantos-tp11-development/v1',validationMode:local?'LOCAL':'UPSTREAM',...(local?{upstreamVerification:{status:'NOT_RUN',checkpoint:'RELEASE-GATE:BETA',externalExecution:false,currentPublicBytesVerified:false}}:{}),nodeId:'CORE:TP11',stage:'DEVELOPMENT',status:dependencies.every(d=>d.status==='READY')?'READY':'BLOCKED',engineeringStatus:results.every(c=>c.exitCode===0)?'PASS':'FAIL',formalAccepted:false,observedSourceCommit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),environment:{node:process.version,python:execFileSync('engines/.venv/bin/python',['--version'],{encoding:'utf8'}).trim()},planInput:planInput(nodesFromPlans().get('CORE:TP11')),inputs,outputs,checks:results,dependencies,excluded};writeFileSync(resolve(root,directory,'receipt.json'),JSON.stringify(r,null,2)+'\n');return verifyTp11(r,{checkDependencies:false});}
function admit(){const p=resolve(root,directory,'receipt.json'),r=JSON.parse(readFileSync(p));verifyTp11(r,{checkDependencies:false});validateReceipt('CORE:TP11');r.dependencies=deps();assert(r.dependencies.every(d=>d.status==='READY'));r.status='READY';writeFileSync(p,JSON.stringify(r,null,2)+'\n');return verifyTp11(r);}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){try{assert(process.argv.length===3&&['--record','--record-local','--verify','--ready','--admit'].includes(process.argv[2]));const result=process.argv[2]==='--record'||process.argv[2]==='--record-local'?record(process.argv[2]==='--record-local'):process.argv[2]==='--admit'?admit():verifyTp11(JSON.parse(readFileSync(resolve(root,directory,'receipt.json'))));console.log(JSON.stringify(result));if(process.argv[2]==='--ready'&&result.stageGate!=='READY')process.exitCode=2;}catch(e){console.error(e.message.split('\n')[0]);process.exitCode=1;}}
